import {shuffle} from './utils.js';
export const isCorrect=(q,selected)=>selected.length===q.answers.length&&selected.every(id=>q.answers.includes(id));
export function createSession(questions,config){let list=config.shuffleQuestions?shuffle(questions):[...questions];list=list.slice(0,config.length);if(!list.length)throw new Error('No questions match these filters.');return {id:globalThis.crypto?.randomUUID?.()||`session-${Date.now()}-${Math.random().toString(36).slice(2,10)}`,ids:list.map(q=>q.id),index:0,startedAt:Date.now(),elapsed:0,responses:{},optionOrders:Object.fromEntries(list.map(q=>[q.id,(config.shuffleAnswers?shuffle(q.options):q.options).map(o=>o.id)])),config:{...config}}}
export function recordAnswer(state,session,q,selected){if(session.responses[q.id])return false;if(!selected.length)throw new Error('Choose an answer first.');if(selected.some(id=>!q.options.some(o=>o.id===id)))throw new Error('Invalid option.');const correct=isCorrect(q,selected),at=Date.now();session.responses[q.id]={selected:[...selected],correct,at};const p=state.questions[q.id]||{attempts:0,correct:0,incorrect:0};state.questions[q.id]={...p,attempts:p.attempts+1,correct:p.correct+(correct?1:0),incorrect:p.incorrect+(correct?0:1),lastCorrect:correct,lastAt:at,lastSelected:[...selected]};return true}
export function score(s){const responses=Object.values(s.responses);const correct=responses.filter(r=>r.correct).length;return {total:s.ids.length,correct,incorrect:responses.length-correct,unanswered:s.ids.length-responses.length,score:Math.round(correct/s.ids.length*100),accuracy:responses.length?Math.round(correct/responses.length*100):0}}
export function statistics(s){const items=Object.values(s.questions);return {attempts:items.reduce((n,q)=>n+q.attempts,0),correct:items.reduce((n,q)=>n+q.correct,0),incorrect:items.reduce((n,q)=>n+q.incorrect,0),unique:items.length,sessions:s.history.length,unanswered:s.history.reduce((n,h)=>n+score(h).unanswered,0)}}
